# Variable mapping: edge (i,j) with i<j -> variable index
# We'll use 1-indexed variables
def var(i, j):
    if i > j:
        i, j = j, i
    return i * n + j + 1

# Let's try a different approach. Instead of encoding maximality in CNF directly,
# let's use a SAT solver to find a triangle-free graph, then check maximality.
# We can iterate: find a triangle-free graph, check if maximal, if not, add constraints.

# First, let's just find any triangle-free graph with the fixed edges.

c = CNF()

# Fixed edges
for (i,j) in fixed_edges:
    c.append([var(i,j)])

