from pysat.formula import CNF
from pysat.solvers import Solver
import itertools

n = 8
fixed_edges = [(0,6), (2,6)]

def var(i, j):
    if i > j:
        i, j = j, i
    return i * n + j + 1

# Let's encode maximality properly using auxiliary variables.
# For each pair (i,j), we need: e_ij OR (exists k: e_ik AND e_jk)
# 
# We can introduce auxiliary variables a_ijk for each triple (i,j,k) with i<j, k != i,j
# a_ijk means "k witnesses the triangle for non-edge (i,j)", i.e., e_ik AND e_jk
# 
# Then for each (i,j): e_ij OR (OR over k of a_ijk)
# And for each (i,j,k): a_ijk -> (e_ik AND e_jk), i.e., (not a_ijk OR e_ik) AND (not a_ijk OR e_jk)

c = CNF()

# Fixed edges
for (i,j) in fixed_edges:
    c.append([var(i,j)])

# No triangles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            c.append([-var(i,j), -var(i,k), -var(j,k)])

# Maximality encoding
# Auxiliary variables: a_ijk for i<j, k != i,j
# We'll use a large offset for auxiliary variables
aux_offset = n * n + 1  # max var index for edges is n*n

def aux_var(i, j, k):
    """Variable for: k witnesses triangle for non-edge (i,j)"""
    if i > j:
        i, j = j, i
    # Use a unique index
    return aux_offset + i * n * n + j * n + k

# For each pair (i,j) with i<j:
# e_ij OR (OR over k of a_ijk)
# And for each k: a_ijk -> e_ik AND a_ijk -> e_jk

for i in range(n):
    for j in range(i+1, n):
        # e_ij OR (OR over k of a_ijk)
        clause = [var(i,j)]
        for k in range(n):
            if k != i and k != j:
                clause.append(aux_var(i,j,k))
        c.append(clause)

        # For each k: a_ijk -> e_ik and a_ijk -> e_jk
        for k in range(n):
            if k != i and k != j:
                c.append([-aux_var(i,j,k), var(i,k) if i < k else var(k,i)])
                c.append([-aux_var(i,j,k), var(j,k) if j < k else var(k,j)])

print(f"Number of clauses: {len(c.clauses)}")
print(f"Number of variables: {c.nv}")

solver = Solver(bootstrap_with=c)
if solver.solve():
    model = solver.get_model()
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if model[var(i,j)-1] > 0:
                edges.append((i,j))
    print(f"Found maximal triangle-free graph: {edges}")

    # Verify
    edge_set = set(edges)
    # Check triangle-free
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if (i,j) in edge_set and (i,k) in edge_set and (j,k) in edge_set:
                    print(f"ERROR: Triangle {i},{j},{k}")
    # Check maximality
    for i in range(n):
        for j in range(i+1, n):
            if (i,j) not in edge_set:
                found = False
                for k in range(n):
                    if k != i and k != j:
                        if ((i,k) in edge_set or (k,i) in edge_set) and ((j,k) in edge_set or (k,j) in edge_set):
                            found = True
                            break
                if not found:
                    print(f"ERROR: Not maximal, can add edge ({i},{j})")
    print("Verification done")
else:
    print("UNSATISFIABLE - no maximal triangle-free graph with these fixed edges")

